describe('Tablet Layout - Two-Column Grid', () => {
  beforeEach(() => {
    cy.visit('/tablet-layout');
  });

  it('should switch to two-column grid layout on tablet viewport', () => {
    // Verify initial desktop layout
    cy.get('[data-testid="desktop-layout"]').should('be.visible');
    cy.get('[data-testid="desktop-grid-item"]').should('have.class', 'grid-item');
    cy.get('[data-testid="desktop-grid-item"]').should('have.css', 'width', '50%');

    // Trigger tablet viewport
    cy.intercept('GET', '/api/layouts/tablet').as('tabletLayout');
    cy.get('[data-testid="toggle-layout-button"]').click();
    cy.wait('@tabletLayout');

    // Verify two-column grid layout
    cy.get('[data-testid="tablet-layout"]').should('be.visible');
    cy.get('[data-testid="tablet-grid-item"]').should('have.class', 'grid-item');
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'width', '50%');
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'margin-right', '5px');

    // Verify responsive breakpoints
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'min-width', '320px');
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'max-width', '640px');
  });

  it('should handle edge case: tablet viewport with very narrow screen', () => {
    // Trigger tablet viewport with narrow screen
    cy.intercept('GET', '/api/layouts/tablet').as('tabletLayout');
    cy.get('[data-testid="toggle-layout-button"]').click();
    cy.wait('@tabletLayout');

    // Verify layout adapts to very narrow screen
    cy.get('[data-testid="tablet-layout"]').should('be.visible');
    cy.get('[data-testid="tablet-grid-item"]').should('have.class', 'grid-item');
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'width', '100%');

    // Verify no margin on last item
    cy.get('[data-testid="tablet-grid-item"]:last-child').should('have.css', 'margin-right', '0px');

    // Verify responsive breakpoints still apply
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'min-width', '320px');
    cy.get('[data-testid="tablet-grid-item"]').should('have.css', 'max-width', '640px');
  });
});
